.mtp-stage.fin .mtp-pair-card .tri-result .tri-piece{width:43px;height:43px;font-size:38px;}
.mtp-stage.fin .mtp-pair-card .mpc-w{font-size:26px;line-height:1.05;}
.mtp-stage.fin .mtp-pair-card .mpc-bridge{position:relative;width:34px;height:54px;flex:none;z-index:1;}
