@keyframes mtpResultCardIn{0%{opacity:0;transform:translateY(24px) scale(.82)}100%{opacity:1;transform:none}}
@keyframes mtpResultOne{0%{opacity:0;transform:translateX(-70px) rotate(-8deg) scale(.75)}100%{opacity:1;transform:none}}
@keyframes mtpResultMany{0%{opacity:0;transform:translateX(70px) rotate(8deg) scale(.75)}100%{opacity:1;transform:none}}
@keyframes mtpResultArrow{0%{opacity:0;transform:scale(.25)}100%{opacity:1;transform:scale(1)}}
