.mtp-bubble{position:absolute;border-radius:50%;border:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;cursor:pointer;
  background:transparent url("assets/Images/bubble_blue.png") center/100% 100% no-repeat;
  box-shadow:none;
  transition:transform .16s ease,box-shadow .2s ease,opacity .3s ease,filter .3s ease;}
/* [r41] The gentle bob is now driven in JS so the bubbles can actually meet each other; this CSS
   keyframe is kept only for reduced-motion, where the drift loop does not run at all. */
@media (prefers-reduced-motion:reduce){
  .mtp-bubble:not(.sel):not(.ok):not(.burst):not(.fly):not(.bounce):not(.wiggle){animation:mtpFloat var(--floatDur,4.8s) ease-in-out infinite;animation-delay:var(--floatDelay,0s);}
}
@keyframes mtpFloat{0%,100%{transform:translateY(0) rotate(-.5deg)}50%{transform:translateY(-9px) rotate(.5deg)}}

.mtp-bubble:hover{transform:translateY(-4px) scale(1.03);}
.mtp-bubble .mtp-icons{display:flex;align-items:center;justify-content:center;gap:2px;line-height:1;}
.mtp-bubble .mtp-ico{width:var(--ico);height:var(--ico);object-fit:contain;}
.mtp-bubble .mtp-ico-emo{font-size:var(--ico);line-height:1;}
.mtp-bubble{--tri:var(--ico);}   /* the bubble's icon size drives its "many" art too */
.mtp-bubble .tri-bubble{width:calc(var(--ico) * 2.35);height:calc(var(--ico) * 1.75);}
.mtp-bubble .tri-bubble .tri-piece{width:calc(var(--ico) * 1.08);height:calc(var(--ico) * 1.08);font-size:calc(var(--ico) * .95);}
.mtp-bubble .mtp-word{font-weight:800;color:var(--navy);line-height:1.05;white-space:nowrap;text-shadow:0 1px 0 rgba(255,255,255,.7);}
.mtp-bubble.sel{box-shadow:0 0 0 7px var(--selected),0 0 30px rgba(56,106,246,.55),0 10px 22px rgba(11,61,140,.22);transform:scale(1.05);}
.mtp-bubble.ok{box-shadow:0 0 0 7px var(--correct),0 0 34px rgba(0,177,50,.55),0 10px 22px rgba(11,61,140,.22);transform:scale(1.06);}
.mtp-bubble.faded{opacity:.26;filter:grayscale(.5);pointer-events:none;}
.mtp-bubble.pulse{animation:mtpPulse .85s ease-in-out;}
.mtp-bubble.pulse-hold{animation:mtpPulse 1.1s ease-in-out infinite;}
.mtp-bubble.intro-pulse{animation:mtpIntroPulse 1s ease-in-out 2;z-index:18;}
.mtp-bubble.wiggle{animation:mtpWiggle .72s cubic-bezier(.36,.07,.19,.97)!important;transform-origin:center center;z-index:25;}
/* a correct pair: bounce on the spot the instant the tap lands, then fly into the tray card */
.mtp-bubble.bounce{animation:mtpBounce .42s cubic-bezier(.34,1.6,.5,1);pointer-events:none;}
@keyframes mtpBounce{0%{transform:scale(1.06);}32%{transform:scale(1.30);}62%{transform:scale(.92);}100%{transform:scale(1.08);}}
.mtp-bubble.burst{pointer-events:none;animation:mtpBurst .68s cubic-bezier(.18,.72,.22,1) forwards;z-index:24;}
.mtp-bubble.burst .mtp-icons,.mtp-bubble.burst .mtp-word{animation:mtpBurstContent .22s ease-out forwards;}
.mtp-bubble.burst::after{content:"";position:absolute;inset:5%;border:5px solid rgba(184,239,255,.92);border-radius:50%;animation:mtpBurstRing .66s ease-out forwards;}
@keyframes mtpBurst{
  0%{transform:scale(1);opacity:1;filter:saturate(1)}
  20%{transform:scale(1.12,.94);opacity:1;filter:saturate(1.2) brightness(1.06)}
  34%{transform:scale(.96,1.10);opacity:1}
  43%{transform:scale(1.18);opacity:0}
  100%{transform:scale(1.28);opacity:0}
}
@keyframes mtpBurstContent{0%{opacity:1;transform:scale(1)}100%{opacity:0;transform:scale(.72)}}
@keyframes mtpBurstRing{0%{transform:scale(.72);opacity:.95}48%{opacity:.8}100%{transform:scale(1.72);opacity:0}}
.bubble-pop-fx{position:absolute;width:1px;height:1px;z-index:28;pointer-events:none;}
.bubble-pop-ring{position:absolute;left:0;top:0;width:42px;height:42px;margin:-21px;border:4px solid rgba(168,236,255,.92);border-radius:50%;
  box-shadow:0 0 14px rgba(132,206,255,.78),inset 0 0 9px rgba(239,193,255,.85);animation:bubblePopRing .64s ease-out forwards;}
.bubble-droplet{position:absolute;left:0;top:0;width:var(--sz);height:calc(var(--sz) * .48);margin-left:calc(var(--sz) * -.5);margin-top:calc(var(--sz) * -.24);
  border-radius:50%;background:linear-gradient(110deg,#fff 0 20%,#72dcff 44%,#b994ff 76%,#ffd1ef 100%);
  box-shadow:0 0 7px rgba(80,188,255,.82);transform:rotate(var(--rot)) scale(.2);opacity:0;animation:bubbleDropletFly .66s cubic-bezier(.12,.68,.2,1) var(--delay) forwards;}
@keyframes bubblePopRing{0%{transform:scale(.25);opacity:1}100%{transform:scale(3.4);opacity:0}}
@keyframes bubbleDropletFly{
  0%{transform:translate(0,0) rotate(var(--rot)) scale(.2);opacity:0}
  12%{opacity:1}
  68%{opacity:.96}
  100%{transform:translate(var(--dx),var(--dy)) rotate(calc(var(--rot) + 150deg)) scale(.78);opacity:0}
}
.mtp-bubble.fly{transition:transform .62s cubic-bezier(.55,-0.06,.5,1),opacity .5s ease .16s;z-index:30;pointer-events:none;}
@keyframes mtpPulse{0%,100%{transform:scale(1);}45%{transform:scale(1.13);}}
@keyframes mtpIntroPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.065)}}
@keyframes mtpWiggle{0%,100%{transform:translateX(0) rotate(0);}12%{transform:translateX(-16px) rotate(-6deg);}28%{transform:translateX(14px) rotate(5deg);}44%{transform:translateX(-12px) rotate(-4deg);}60%{transform:translateX(10px) rotate(3deg);}76%{transform:translateX(-7px) rotate(-2deg);}90%{transform:translateX(4px) rotate(1deg);}}


/* ============ REVIEW-DECK FIXES ============ */

/* [layout bug] .tut-content was an unclipped flex:1 box, so any module taller than the card
   punched straight through the prompt above it and the mascot/आगे below (seen on every
   tutorial screen). Give the frame a real content box that its children size against. */
.tut-content{overflow:hidden;}
.tut-content > *{max-height:100%;}
/* deck pp.4,6,8,10: "no instructional panel in this slide" — the story beats drop the heading
   and hand the whole card to the picture + the poem text. */
.stage.tut .tut-card.no-prompt .tut-prompt{display:none;}

/* volume chip sat ON Swiftee's satchel — nudge it clear of the body on both the card and the
   landing screen (still shoulder-adjacent, just not touching). */

/* ---- STORY_SCENE (deck pp.4,6,8,10) ----
   Picture on top, poem below; lines arrive one at a time and the target words burn orange.
   Image 1 rides the first stanza, image 2 the second. */
.story-scene{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;gap:14px;padding:4px 0;}
/* [r22] the poem picture was flush against the top of the card too. This needs .stage.tut to beat
   the tutorial rule that zeroes the padding. */
.stage.tut .story-scene{padding-top:26px;}
.story-stage{flex:1;min-height:0;width:100%;display:flex;align-items:center;justify-content:center;}
.story-frame{height:100%;aspect-ratio:16/9;max-width:100%;border-radius:26px;overflow:hidden;position:relative;
  background:#F7EFE0;border:5px solid #FFF;box-shadow:0 12px 32px rgba(11,42,90,.18),0 3px 10px rgba(11,42,90,.10);}
.story-frame .story-img{width:100%;height:100%;object-fit:contain;display:block;}
.story-frame .story-img.swap{animation:storyFade .55s ease;}
@keyframes storyFade{from{opacity:0;transform:scale(1.04);}to{opacity:1;transform:none;}}
.story-fallback{font-size:150px;line-height:1;display:flex;align-items:center;justify-content:center;width:100%;height:100%;}
.story-caption{flex-shrink:0;font-family:var(--font-hi);font-weight:800;color:var(--navy);text-align:center;
  background:#FFF3C7;border:3px solid #FCD86B;border-radius:20px;padding:10px 30px;max-width:1000px;
  box-shadow:0 4px 14px rgba(11,42,90,.10);display:flex;flex-direction:column;gap:2px;}
.story-caption .ln{font-size:29px;line-height:1.28;opacity:0;transform:translateY(8px);
  transition:opacity .4s ease,transform .4s ease;}
.story-caption .ln.in{opacity:1;transform:none;}
.story-caption .poem-word{display:inline-block;white-space:pre;transform-origin:50% 75%;opacity:.96;
  transform:translateY(0) scale(1);filter:drop-shadow(0 0 0 rgba(56,106,246,0));
  transition:transform .72s cubic-bezier(.2,.72,.25,1),filter .72s ease,opacity .5s ease;}
.story-caption .poem-word.is-speaking{opacity:1;transform:translateY(-3px) scale(1.075);
  filter:drop-shadow(0 2px 8px rgba(56,106,246,.58));}
.story-caption .poem-word.hl-orange.is-speaking{filter:drop-shadow(0 2px 9px rgba(242,128,30,.68));}
/* deck: "Highlight the bold words in orange." */
/* [r24] THE highlight glow, defined once for the whole lesson. The halo breathes in and out four
   times and then goes out, leaving the word orange — a single flash was too easy to miss, and a
   permanent halo stopped drawing the eye at all. Only the GLOW moves: the letter never scales,
   because the pulse pulled attention to the movement instead of to the letter that is different. */
@keyframes wordGlow{
  0%,100%{text-shadow:0 0 0 rgba(247,161,54,0);}
  50%    {text-shadow:0 0 22px rgba(247,161,54,.95), 0 0 8px rgba(247,161,54,.7);}
}
.hl-orange{color:#F2801E;}
/* Story sentences stay visually calm. Glow is reserved for the changed suffix on comparison screens. */
.story-caption .hl-orange{color:#F2801E;animation:none!important;text-shadow:none!important;}
.story-caption.many-lines{gap:0;padding-top:8px;padding-bottom:8px;}
.story-caption.many-lines .ln{font-size:24px;line-height:1.18;}

/* ---- COMPARE_VACHAN — "शब्दों की तुलना" (deck pp.5,7,9,11) ----
   Deck removals applied: no heading, no एक…/बहुत सारे… captions, no "आ की मात्रा → ए की मात्रा" row.
   Kept: the two picture cards, the two word cards, and the spoken line in its OST box.
   Deck animation note: the WHOLE word shows first, then only the changed part pulses/glows. */
/* [r22] Two COLUMNS, not two rows. The pictures and the words used to be separate centred flex
   rows, so a word only landed under the middle of its picture by coincidence — with pictures of
   different widths it drifted off to one side. Each picture now shares a grid column with its own
   word, which makes "the word sits exactly under the middle of its picture" true by construction,
   whatever the artwork ratio turns out to be. */
.cmpv{flex:1;min-height:0;display:grid;
  grid-template-columns:auto auto;grid-template-rows:1fr auto;
  justify-content:center;justify-items:center;align-items:center;
  column-gap:34px;row-gap:14px;
  padding:30px 0 6px;}            /* the pictures were pressed against the top of the card */
/* the two wrappers step out of the layout so their children join the grid above */
.cmpv-pics,.cmpv-words{display:contents;}
.cmpv-pic{height:100%;aspect-ratio:16/10;max-width:47%;overflow:hidden;
  background:var(--pic-mat);border:var(--pic-border);border-radius:var(--pic-radius);box-shadow:var(--pic-shadow);}
.cmpv-pic img{width:100%;height:100%;object-fit:contain;display:block;}   /* contain, never cover — a cropped illustration loses the character the line is about */
.cmpv-pic .cmpv-emo{width:100%;height:100%;display:flex;align-items:center;justify-content:center;font-size:96px;}

/* The friend artwork is supplied on a portrait canvas, unlike the lesson's other scene art.
   Keep its presentation card the same landscape size as every other picture card, then balance
   the two drawings so one friend and the three friends read at the same visual scale. */
.story-frame.saheli-card,
.cmpv-pic.saheli-card{aspect-ratio:1672/941 !important;}
.story-frame.saheli-single .story-img,
.cmpv-pic.saheli-single img{scale:.88;}
.story-frame.saheli-many .story-img,
.cmpv-pic.saheli-many img{scale:1.11;}

.cmpv-word{min-width:330px;background:#fff;border:4px solid #5AAFF2;border-radius:20px;padding:8px 26px;
  text-align:center;font-weight:800;font-size:54px;color:var(--navy);line-height:1.15;
  box-shadow:0 5px 0 rgba(11,61,140,.08),0 8px 18px rgba(11,42,90,.12);
  opacity:0;transform:translateY(10px);transition:opacity .35s ease,transform .35s ease;}
.cmpv-word.in{opacity:1;transform:none;}
.cmpv-word .chg{display:inline-block;transition:color .3s ease,text-shadow .3s ease;}
/* [r23] The word arrives entirely in navy. When it is time to show what changed, ONLY the changed
   syllable turns orange and glows — it no longer scales in and out. The pulse pulled the eye to
   the movement instead of to the letter that is different, which is the whole point of the screen. */
.cmpv-word.lit .chg{color:#F2801E;animation:wordGlow 1.05s ease-in-out 4;}
.cmpv-ost{flex-shrink:0;font-weight:800;font-size:28px;color:var(--navy);text-align:center;line-height:1.25;
  background:#FFF3C7;border:3px solid #FCD86B;border-radius:18px;padding:9px 28px;max-width:1000px;
  box-shadow:0 4px 14px rgba(11,42,90,.10);opacity:0;transition:opacity .4s ease;}
.cmpv-ost.in{opacity:1;}


/* ---- PICK_VACHAN_WORD — deck pp.12-17 "सही शब्द चुनिए।" ----
   source word (with its quantity picture) → dashed drop box (with the TARGET quantity picture and
   its एक/अनेक pill above it) → three word options below. Tap an option to fill the box. */
.pvw{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:30px;margin:0 -80px;}
.pvw-row{display:flex;align-items:flex-end;justify-content:center;gap:26px;}
.pvw-side{display:flex;flex-direction:column;align-items:center;gap:8px;}
.pvw-pill{background:#fff;border:3px solid #5AAFF2;border-radius:999px;padding:3px 26px;font-size:24px;font-weight:800;color:var(--navy);}
.pvw-qty{display:flex;align-items:flex-end;justify-content:center;gap:6px;min-height:86px;}
.pvw-qty img{width:78px;height:78px;object-fit:contain;}
.pvw-qty img.pvw-group{width:250px;height:88px;}
.pvw-qty .pvw-emo{font-size:62px;line-height:1;}
.pvw-qty.pulse{animation:pvwPulse .9s ease-in-out 2;}
.pvw-src{width:420px;height:96px;box-sizing:border-box;background:#fff;border:4px solid #8FC7F5;border-radius:22px;padding:12px 30px;text-align:center;
  display:flex;align-items:center;justify-content:center;font-size:56px;font-weight:800;color:var(--navy);cursor:pointer;box-shadow:0 5px 0 rgba(11,61,140,.08),0 8px 18px rgba(11,42,90,.12);}
.pvw-src.pulse{animation:pvwPulse .9s ease-in-out 2;}
/* [r28] The arrow points from the left box to the right one, so it belongs on THEIR centre line.
   It used to hang off the bottom of the row with a guessed padding, which left it riding above the
   boxes. Giving it a slot the same height as those boxes (96px, matching .pvw-src/.pvw-box) and
   centring the glyph inside it puts it exactly halfway up them, whatever the font metrics do. */
.pvw-arrow{font-size:52px;color:#5AAFF2;font-weight:800;line-height:1;
  align-self:flex-end;height:96px;display:flex;align-items:center;justify-content:center;padding:0;}
.pvw-box{width:420px;height:96px;box-sizing:border-box;border:4px dashed #5AAFF2;border-radius:22px;background:#F4FAFF;
  display:flex;align-items:center;justify-content:center;font-size:56px;font-weight:800;color:var(--navy);}
.pvw-box.filled{border-style:solid;background:var(--correct-bg);border-color:var(--correct);}
.pvw-opts{display:flex;justify-content:center;gap:26px;flex-wrap:wrap;}
.pvw-opt{min-width:236px;background:#fff;border:4px solid #8FC7F5;border-radius:20px;padding:10px 26px;text-align:center;
  font-size:38px;font-weight:800;color:var(--navy);cursor:pointer;transition:transform .15s ease,opacity .35s ease,border-color .2s ease;
  box-shadow:0 5px 0 rgba(11,61,140,.08),0 8px 18px rgba(11,42,90,.12);}
.pvw-opt:hover{transform:translateY(-4px);}
.pvw-opt.wiggle{animation:mtpWiggle .55s ease-in-out;}
.pvw-opt.lit{border-color:#F3A81B;animation:pvwPulse 1s ease-in-out infinite;}
.pvw-opt.gone{opacity:.28;pointer-events:none;box-shadow:none;}      /* deck: "बाकी options fade हो जाएँ" */
.pvw-opt.taken{opacity:0;pointer-events:none;}
@keyframes pvwPulse{0%,100%{transform:scale(1);}45%{transform:scale(1.09);}}


/* ---- FILL_VACHAN_DRAG — part 2, levelled (built to the demo preview.html) ----
   Deliberately bare: no photos, no icons, no side panel. A slim progress bar carrying the स्तर
   label and a star count on top, two sentence cards in the middle, clean word tiles below.
   The slide host is ~493 design px tall, so every band here is a fixed budget: 34 (top) +
   14 + 2x92 (cards) + 14 + 100 (bank) leaves slack rather than overflowing like the first cut. */
.fvd{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;gap:14px;margin:0 -60px;overflow:hidden;}
.fvd-top{width:1120px;max-width:100%;display:flex;align-items:center;gap:16px;flex-shrink:0;height:34px;}
.fvd-level{font-size:20px;font-weight:800;color:var(--navy);white-space:nowrap;}
.fvd-bar{flex:1;height:14px;border-radius:999px;background:#DCEAF6;overflow:hidden;box-shadow:inset 0 2px 4px rgba(11,61,140,.13);}
.fvd-bar-fill{height:100%;width:0;border-radius:inherit;background:linear-gradient(90deg,#39B979,#61D497);transition:width .45s ease;}
.fvd-stars{font-size:22px;font-weight:800;color:var(--navy);white-space:nowrap;}

.fvd-body{flex:1;min-height:0;width:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;overflow:hidden;}
.fvd-cards{width:100%;display:flex;flex-direction:column;align-items:center;gap:14px;flex-shrink:0;}
.fvd-card{width:1080px;max-width:100%;min-height:92px;box-sizing:border-box;background:#fff;
  border:3px solid #D6E6F3;border-bottom:6px solid #C1D6E6;border-radius:20px;padding:8px 24px;
  display:flex;align-items:center;justify-content:center;flex-wrap:nowrap;gap:12px;
  text-align:center;font-size:33px;font-weight:800;color:var(--navy);line-height:1.3;white-space:nowrap;
  box-shadow:0 5px 14px rgba(23,77,132,.09);transition:border-color .25s ease,background .25s ease;}
.fvd-card.pulse{animation:fvdPulse .85s ease-in-out 2;border-color:#FFA914;}
/* a correct answer colours the WORD, never the whole sentence card: greening the full rectangle
   made the sentence itself look like the thing that was marked right. */
.fvd-card.done{border-color:#D6E6F3;border-bottom-color:#C1D6E6;background:#fff;}
/* the blank IS a .dd-zone, so the engine's 150x150 zone box has to be undone explicitly */
.fvd-card .fvd-blank{width:230px;height:62px;min-width:230px;min-height:62px;flex:0 0 230px;
  display:inline-flex;flex-direction:row;align-items:center;justify-content:center;gap:0;
  border:3px dashed #70AEE1;border-radius:12px;background:#F7FBFF;
  font-size:32px;font-weight:800;color:var(--navy);line-height:1;padding:2px 14px;box-sizing:border-box;
  transition:background .2s ease,border-color .2s ease,box-shadow .2s ease;}
.fvd-card .fvd-blank.hover{border-color:#FFA914;background:#FFF9E6;border-width:3px;
  box-shadow:0 0 0 5px rgba(255,207,112,.35);}
.fvd-card .fvd-blank.filled{border-style:solid;border-width:3px;border-color:var(--correct);
  background:#E2FBEC;color:#17794A;box-shadow:0 0 0 4px rgba(0,177,50,.15);}
.fvd-card .fvd-blank.lit{animation:fvdGlow 1s ease 2;}

.fvd-bank{width:1080px;max-width:100%;flex-shrink:0;border-top:0;padding-top:37px;}
.fvd-tiles{display:flex;justify-content:center;gap:24px;min-height:62px;}
.fvd-tile{width:230px;height:62px;min-width:230px;min-height:62px;box-sizing:border-box;border:3px solid #B6CDE0;
  border-radius:14px;background:#fff;color:var(--navy);padding:2px 14px;text-align:center;display:flex;align-items:center;justify-content:center;
  font-size:31px;font-weight:800;line-height:1.2;white-space:nowrap;
  cursor:grab;touch-action:none;user-select:none;box-shadow:0 5px 10px rgba(23,77,132,.09);
  transition:opacity .25s ease,box-shadow .18s ease;}
.fvd-tile:hover{background:#F5FAFF;}
.fvd-tile.dragging{cursor:grabbing;z-index:50;box-shadow:0 14px 26px rgba(56,106,246,.3);transition:none;}
.fvd-tile.wiggle{animation:mtpWiggle .55s ease-in-out;}
.fvd-tile.lit{animation:fvdGlow 1s ease 2;border-color:#FFA914;}
/* [r27] A placed word disappears from the bank outright. Leaving a faint ghost of it behind read
   as a half-there word the child could not touch, which is confusing rather than informative.
   visibility rather than display, so the tile that is still in play does not jump sideways. */
.fvd-tile.used{visibility:hidden;pointer-events:none;}
@keyframes fvdPulse{0%,100%{transform:scale(1);}50%{transform:scale(1.03);}}
@keyframes fvdGlow{0%,100%{transform:scale(1);}50%{transform:scale(1.06);box-shadow:0 0 22px #FFAD1F;}}

/* स्तर-पूरा and the closing summary — the demo's between-level beats, kept inside the slide */
.fvd-panel{flex:1;min-height:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;text-align:center;}
/* [r32] the supplied स्तर-पूरा lockup. The stars are three copies of one cutout at the sizes the
   artwork uses — small, large, small — so each can be popped in on its own. */
.fvd-panel-stars{display:flex;align-items:center;justify-content:center;gap:6px;height:104px;}
.fvd-panel-stars img{height:68px;width:auto;opacity:0;transform:scale(.3) translateY(26px);
  filter:drop-shadow(0 4px 6px rgba(11,42,90,.18));}
.fvd-panel-stars img.mid{height:104px;}
.fvd-panel-stars img.pop{animation:starDrop .52s cubic-bezier(.34,1.56,.55,1) forwards;}
@keyframes starDrop{
  0%  {opacity:0;transform:scale(.3) translateY(26px);}
  60% {opacity:1;transform:scale(1.18) translateY(-6px);}
  100%{opacity:1;transform:scale(1) translateY(0);}
}
.fvd-panel-ttl{font-size:42px;font-weight:800;color:var(--navy);line-height:1.15;}
.fvd-panel-ttl img{height:104px;width:auto;max-width:100%;display:block;}
.fvd-panel-sub{font-size:23px;font-weight:700;color:var(--navy-dk);opacity:.9;}
/* [r33] The अगला स्तर button now wears the supplied artwork. It stays a real <button> — a picture
   of a button cannot be tapped, focused or announced — so the image sits inside it and the element
   itself drops its own chrome. */
.fvd-panel-btn{background:none;border:0;padding:0;cursor:pointer;line-height:0;
  filter:drop-shadow(0 8px 14px rgba(23,77,132,.18));transition:transform .12s ease;}
.fvd-panel-btn img{height:90px;width:auto;display:block;}
.fvd-panel-btn:hover{transform:translateY(-2px);}
.fvd-panel-btn:active{transform:translateY(3px);}
.fvd-panel-btn:focus-visible{outline:4px solid var(--selected);outline-offset:6px;border-radius:999px;}
.fvd-summary{display:grid;grid-template-columns:repeat(3,auto);gap:8px 14px;margin-top:2px;}
.fvd-summary span{background:#fff;border:2px solid #B7DCFA;border-radius:12px;padding:6px 14px;
  font-size:21px;font-weight:800;color:var(--navy);white-space:nowrap;}

/* ===== OCEAN WORLD — lesson-specific game skin ==========================================
   The bubble and sentence games now belong to one continuous underwater world. This is kept
   asset-light on purpose: the supplied bubble artwork remains the hero, while depth, moving
   caustics and tiny background bubbles are painted with CSS. No decorative SVG scene has been
   inserted in place of real artwork. */
@keyframes oceanCaustics{
  0%  {background-position:0 0,0 0,0 0;transform:translate3d(-1.5%,0,0) scale(1.04);}
  50% {background-position:110px 32px,-80px 46px,45px -28px;transform:translate3d(1.5%,-1%,0) scale(1.08);}
  100%{background-position:220px 64px,-160px 92px,90px -56px;transform:translate3d(-1.5%,0,0) scale(1.04);}
}
@keyframes oceanBubblesRise{
  0%{background-position:26px 520px,180px 610px,420px 560px,720px 640px,990px 590px;opacity:.22;}
  50%{opacity:.5;}
  100%{background-position:44px -70px,205px -120px,390px -95px,750px -150px,1025px -90px;opacity:.24;}
}

.mtp-stage,.fvd{
  isolation:isolate;
  border-radius:32px;
  background:
    radial-gradient(ellipse at 50% -12%,rgba(255,255,255,.94) 0 7%,rgba(218,249,255,.64) 25%,transparent 52%),
    linear-gradient(180deg,#DDF8FF 0%,#B6ECF8 47%,#83D2E8 100%);
  box-shadow:inset 0 0 0 3px rgba(255,255,255,.72),inset 0 -30px 60px rgba(12,111,159,.12),0 10px 28px rgba(14,97,143,.13);
  overflow:hidden;
}
.mtp-stage::before,.fvd::before{
  content:"";position:absolute;z-index:-2;inset:-12%;pointer-events:none;
  background:
    repeating-linear-gradient(112deg,transparent 0 74px,rgba(255,255,255,.15) 84px 94px,transparent 108px 154px),
    repeating-linear-gradient(68deg,transparent 0 104px,rgba(154,242,255,.18) 114px 128px,transparent 142px 204px),
    radial-gradient(ellipse at 50% 16%,rgba(255,255,255,.52),transparent 48%);
  filter:blur(5px);animation:oceanCaustics 10s ease-in-out infinite alternate;
}
.mtp-stage::after,.fvd::after{
  content:"";position:absolute;z-index:-1;inset:0;pointer-events:none;
  background-image:
    radial-gradient(circle,rgba(255,255,255,.72) 0 3px,transparent 4px),
    radial-gradient(circle,rgba(255,255,255,.58) 0 5px,transparent 6px),
    radial-gradient(circle,rgba(233,252,255,.66) 0 2px,transparent 3px),
    radial-gradient(circle,rgba(255,255,255,.48) 0 7px,transparent 8px),
    radial-gradient(circle,rgba(226,250,255,.58) 0 4px,transparent 5px);
  background-repeat:no-repeat;animation:oceanBubblesRise 12s linear infinite;
}

/* Bubble activity: the word bubbles float over the water, with a glassy solved-pair reef tray. */
.mtp-field,.mtp-tray{position:relative;z-index:1;}
.mtp-tray{width:220px;margin:10px 10px 10px 0;padding:12px 10px;border-radius:24px;
  background:linear-gradient(180deg,rgba(246,253,255,.82),rgba(217,246,250,.72));
  border:2px solid rgba(255,255,255,.9);box-shadow:0 8px 24px rgba(14,91,133,.12);backdrop-filter:blur(5px);}
.mtp-tray-ttl{color:#246F9A;text-shadow:0 1px 0 #fff;}
.mtp-pair-card{background:rgba(255,255,255,.9);border-color:#61BDE7;border-radius:18px 26px 18px 26px;}
.mtp-stage.fin .mtp-tray{margin:14px;padding:24px;background:rgba(238,253,255,.84);}

/* [r43] The ocean backdrop rules that sat here were removed: assets/ocean-games.css already owns
   .ocean-decor and .ocean-sea-video, and its version is the better one. They were added in r38 on a
   false diagnosis — the real reason the backdrop looked unstyled was that the local test server had
   no MIME type for .css, so the whole theme stylesheet was refused by the browser and never applied.
   Keeping a second copy here is exactly the shadowing trap that has already cost three rounds. */

/* Sentence activity: same sea, but the interaction pieces become friendly pebble/shell forms. */
.fvd{position:relative;padding:12px 24px 18px;box-sizing:border-box;}
.fvd-top,.fvd-body{position:relative;z-index:1;}
.fvd-level,.fvd-stars{text-shadow:0 1px 0 rgba(255,255,255,.92);}
.fvd-bar{height:16px;background:rgba(241,253,255,.76);border:2px solid rgba(255,255,255,.88);
  box-shadow:inset 0 2px 6px rgba(18,102,146,.16),0 2px 7px rgba(18,102,146,.09);}
.fvd-bar-fill{background:linear-gradient(90deg,#22B9C9,#4BD6B3 58%,#9AE66E);box-shadow:0 0 12px rgba(37,199,191,.42);}
/* [r38] The sentence card IS the supplied water bar, with the question sitting on top of it.
   [r51] It was a 9-slice border-image — caps from 170px of source drawn 50px wide, middle stretched
   — which gave the right shape but painted in three pieces. The card sits inside a fractional
   transform scale, so the two shared edges landed mid-pixel and neither piece covered them fully;
   the sea showed through as a thin vertical line near each end of every bar. The same slicing is
   now baked into one image at twice the card's size — assets/UI/ui_panel_water_bar.png, resampled
   from the supplied ui_panel_water.png with those same slice values — so the bar is a single paint
   and no join can show. The caps keep exactly the width and shape they had. */
.fvd-card{background:url("assets/UI/ui_panel_water_bar.png") center/100% 100% no-repeat;
  box-shadow:none;border-radius:0;border:0 solid transparent;min-height:104px;}
/* the correct-answer colour lives on the placed word, never on the panel (r19) */
.fvd-card.done{background:url("assets/UI/ui_panel_water_bar.png") center/100% 100% no-repeat;}
.fvd-card .fvd-blank{background:rgba(237,251,255,.9);border-color:#4AB7D8;border-radius:14px;}
.fvd-tile{background:linear-gradient(180deg,#FFFFFF 0%,#DDF8FA 100%);border-color:#4AB7D8;
  border-radius:14px;box-shadow:0 5px 10px rgba(14,104,145,.14),inset 0 2px 0 rgba(255,255,255,.9);}
.fvd-tile:hover{background:linear-gradient(180deg,#fff 0%,#CBF5F4 100%);}
/* [r44] No card behind the स्तर-पूरा artwork and the closing summary — the sea reads better on its
   own, and the lockup already carries its own outline and shadow. Only the positioning and the
   breathing room are kept; the pale panel, its border, blur and drop shadow are gone. */
.fvd-panel{position:relative;z-index:1;padding:18px 34px;background:none;border:0;box-shadow:none;backdrop-filter:none;}
.fvd-summary span{background:rgba(255,255,255,.92);border-color:#65C7DA;border-radius:18px 11px 18px 11px;}

@media (prefers-reduced-motion:reduce){
  .mtp-stage::before,.fvd::before,.mtp-stage::after,.fvd::after{animation:none!important;}
}

/* [r34] A stale COPY of this whole block used to sit here — a Round-14 rebase leftover that, being
   later in the file, quietly beat the real rules above it. Its .fvd-panel-btn kept the old orange
   gradient and 12px 40px padding, which is what drew a second orange rectangle around the button
   artwork. Removed; the block above is the only definition now. */

/* ===== FLN ANIMATION KIT: current-generation overrides BEGIN ===== */
/* Start sky: keep the flight on the element and move the glow to a static-shadow
   pseudo-element whose opacity is composited. This is the toolkit's new version. */
.sg-sky i{animation:sgFly var(--t) linear infinite;animation-delay:var(--d);filter:none;}
.sg-sky i::after{content:"";position:absolute;inset:0;border-radius:inherit;background:inherit;border:inherit;
  filter:drop-shadow(0 0 7px rgba(255,255,255,.95));opacity:0;will-change:opacity;
  animation:sgGlowOpacity var(--g) ease-in-out infinite alternate;animation-delay:var(--gd);}
@keyframes sgGlowOpacity{from{opacity:0;}to{opacity:1;}}

/* Nudge press + ripple: all layers share one 1.3s clock, and the effect is centred
   on the real fingertip rather than on the hand's bounding box. */
.nudge-hand{width:86px;height:108px;filter:drop-shadow(0 6px 10px rgba(0,0,0,.18));animation:none;overflow:visible;}
.nudge-hand .nh-img{display:block;width:100%;height:100%;object-fit:contain;animation:nhTapNew 1.3s ease-in-out infinite;}
.nudge-hand .nh-tapfx{position:absolute;width:94.6px;height:94.6px;left:-13.08px;top:-31.48px;pointer-events:none;z-index:-1;}
.nudge-hand .nh-tapfx i{position:absolute;inset:0;display:block;border-radius:50%;transform-origin:50% 50%;opacity:0;}
.nudge-hand .nh-tapfx .fx-ro{border:5px solid rgba(193,239,254,.78);animation:nhRippleOuter 1.3s ease-out infinite;}
.nudge-hand .nh-tapfx .fx-ri{inset:13px;border:5px solid rgba(193,239,254,.95);animation:nhRippleInner 1.3s ease-out infinite;}
.nudge-hand .nh-tapfx .fx-sp{inset:-4px;background:repeating-conic-gradient(from 8deg,transparent 0 10deg,#FFD359 10deg 14deg,transparent 14deg 45deg);
  -webkit-mask:radial-gradient(circle,transparent 0 53%,#000 55% 68%,transparent 70%);mask:radial-gradient(circle,transparent 0 53%,#000 55% 68%,transparent 70%);
  animation:nhSparkPop 1.3s ease-out infinite;}
@keyframes nhTapNew{0%,100%{transform:translateY(0) scale(1);}45%,62%{transform:translateY(6px) scale(.93);}}
@keyframes nhRippleInner{0%,38%{opacity:0;transform:scale(.30);}47%{opacity:1;transform:scale(.74);}70%{opacity:.5;transform:scale(1.10);}90%,100%{opacity:0;transform:scale(1.34);}}
@keyframes nhRippleOuter{0%,45%{opacity:0;transform:scale(.55);}56%{opacity:.95;transform:scale(.88);}78%{opacity:.4;transform:scale(1.20);}96%,100%{opacity:0;transform:scale(1.46);}}
@keyframes nhSparkPop{0%,42%{opacity:0;transform:scale(.55);}52%{opacity:1;transform:scale(1);}68%{opacity:1;transform:scale(1.06);}86%,100%{opacity:0;transform:scale(1.18);}}

/* One tempo for the answer-feedback pair. */
:root{--fx-beat:.4s;--fx-reward:2;}
.ck-correct{--ckT:calc(var(--fx-beat) * var(--fx-reward));overflow:visible!important;z-index:6;
  background:var(--ck-face,#fff)!important;border-color:var(--correct,#00B132)!important;
  box-shadow:0 6px 16px rgba(0,177,50,.16)!important;
  transition:border-color .07s linear,box-shadow .2s ease!important;
  animation:ckPop calc(var(--ckT) * .68) ease-in-out both!important;}
.ck-correct::after{content:none!important;display:none!important;}
.ck-fx{position:absolute;inset:0;border-radius:inherit;pointer-events:none;z-index:2;}
.ck-crown{position:absolute;inset:0;overflow:visible;}
.ck-crown i{position:absolute;left:50%;top:50%;width:var(--ss);height:var(--ss);margin:calc(var(--ss)/-2) 0 0 calc(var(--ss)/-2);
  background:var(--ck-spark,#FFC93C);clip-path:polygon(50% 0%,61% 35%,98% 35%,68% 57%,79% 91%,50% 70%,21% 91%,32% 57%,2% 35%,39% 35%);
  animation:ckSpark calc(var(--ckT) * .72) cubic-bezier(.15,.7,.35,1) calc(var(--ckT) * .27) both;}
@keyframes ckPop{0%{transform:scale(1);}11%{transform:scale(.966);}50%{transform:scale(1.055);}72%{transform:scale(.992);}100%{transform:scale(1);}}
@keyframes ckSpark{0%{transform:translate(var(--x0),var(--y0)) scale(.3) rotate(0);opacity:0;}25%{opacity:1;}100%{transform:translate(var(--sx),var(--sy)) scale(1) rotate(var(--sr));opacity:0;}}

.wg-wrong,.wg-out{--wgT:var(--fx-beat);overflow:visible!important;z-index:5;background:var(--wg-face,#fff)!important;
  border-color:var(--wrong,#F93544)!important;transition:border-color .07s linear!important;}
.wg-wrong::after,.wg-out::after{content:none!important;display:none!important;}
.wg-wrong{box-shadow:0 6px 16px rgba(249,53,68,.16)!important;animation:wgNo var(--wgT) ease-in-out both!important;}
.wg-fx{position:absolute;inset:0;border-radius:inherit;pointer-events:none;z-index:2;}
.wg-pulse{position:absolute;inset:0;border-radius:inherit;border:3px solid var(--wrong,#F93544);animation:wgPulse calc(var(--wgT) * .62) ease-out both;}
@keyframes wgNo{0%{transform:translateX(0);}18%{transform:translateX(-9px);}38%{transform:translateX(8px);}60%{transform:translateX(-5.5px);}80%{transform:translateX(3px);}100%{transform:translateX(0);}}
@keyframes wgPulse{0%{transform:scale(1.02);opacity:.65;}100%{transform:scale(1.16);opacity:0;}}
.wg-rel{transition:border-color .22s ease,box-shadow .22s ease!important;}

/* Existing scene rings are full-frame mask bands, so use recipe 21's band engine:
   colour carries state; wrong flashes without moving the mask out of register. */
.tis-object-outline{--olT:var(--fx-beat);animation:none;transition:background-color calc(var(--olT) * .175) linear,opacity .2s ease;}
.tis-object-outline.is-wrong{--tis-ring-c:var(--wrong,#F93544);animation:olBandNo var(--olT) linear both!important;}
.tis-object-outline.is-correct{--tis-ring-c:var(--correct,#00B132);animation:olBandYes calc(var(--olT) * 1.35) ease-out both!important;}
@keyframes olBandNo{0%,100%{opacity:1;}20%,60%{opacity:.28;}40%,80%{opacity:1;}}
@keyframes olBandYes{0%{opacity:.55;}30%,100%{opacity:1;}}

html.no-anim .ck-crown,html.no-anim .wg-pulse{display:none;}
html.no-anim .tis-object-outline{animation:none!important;}
@media (prefers-reduced-motion:reduce){.ck-crown,.wg-pulse{display:none}.tis-object-outline{animation:none!important}}
