.ev-text{font-family:var(--font-hi);font-size:25px;line-height:1.72;color:var(--navy);font-weight:600;}
.ev-line{cursor:pointer;border-radius:10px;padding:2px 3px;-webkit-box-decoration-break:clone;box-decoration-break:clone;transition:background .2s,box-shadow .2s;}
.ev-line:hover{background:rgba(56,106,246,.07);}
.ev-line.ev-now{background:#DDEBFF;box-shadow:0 0 0 2px #8BBFFF;}
