.ev-line.ev-pulse{animation:evPulse .9s ease-in-out infinite;}
@keyframes evPulse{0%,100%{filter:none;}50%{filter:brightness(1.08) drop-shadow(0 0 6px rgba(242,183,5,.8));}}
.ev-tag{display:inline-block;font-size:16px;line-height:1.3;font-weight:800;border-radius:999px;padding:1px 10px;margin-right:6px;vertical-align:3px;white-space:nowrap;}
.ev-hl .ev-tag{background:#F2B705;color:#3A2A00;}
.ev-clue .ev-tag{background:#8A63D2;color:#fff;}
/* story read-along page */
.ev-read{flex:1;min-height:0;display:flex;align-items:center;justify-content:center;position:relative;}
